  "routes[route-dbz-saga-androids].localizedName": "La saga de los Androides",
  "routes[route-dbz-saga-androids].group": "Sagas · póster",
  "routes[route-dbz-saga-androids].description": "De la llegada de Trunks del Futuro a la activación de los Androides en el laboratorio del Dr. Gero, hasta los Juegos de Cell. En verde claro en la leyenda del póster.",
  "routes[route-dbz-saga-androids].steps[0].label": "La llegada de Trunks del Futuro",
  "routes[route-dbz-saga-androids].steps[1].label": "Los Androides son activados",
